{ // H1: Standard checkout completes with charged total and recorded steps
var coordinator = new CheckoutCoordinator();
var order = new Order
{
    Reference = "ORD-100",
    Channel = OrderChannel.Web,
    Lines =
    {
        new OrderLine { Sku = "SKU-1", Quantity = 2, UnitPrice = 25m }
    }
};
var customer = new Customer { Tier = CustomerTier.Standard };

var beginResult = coordinator.BeginCheckout(order, customer);
var advanceResult = coordinator.AdvanceStep("payment");
var completeResult = coordinator.CompleteCheckout(order, customer);

Check.Equal("ok", beginResult);
Check.True(advanceResult);
Check.Equal("charged 50", completeResult);
Check.Equal(3, coordinator.StepCount);
}
{ // E1: Beginning checkout with an empty order leaves no completed steps
var coordinator = new CheckoutCoordinator();
var order = new Order
{
    Reference = "ORD-EMPTY",
    Channel = OrderChannel.Web
};
var customer = new Customer { Tier = CustomerTier.Standard };

var result = coordinator.BeginCheckout(order, customer);

Check.Equal("empty order", result);
Check.Equal(0, coordinator.StepCount);
}
{ // B1: Web tender changes only above the five hundred goods threshold
var coordinator = new CheckoutCoordinator();
var customer = new Customer { Tier = CustomerTier.Standard };
var belowOrder = new Order
{
    Reference = "ORD-499",
    Channel = OrderChannel.Web,
    Lines =
    {
        new OrderLine { Sku = "SKU-499", Quantity = 1, UnitPrice = 499m }
    }
};
var atOrder = new Order
{
    Reference = "ORD-500",
    Channel = OrderChannel.Web,
    Lines =
    {
        new OrderLine { Sku = "SKU-500", Quantity = 1, UnitPrice = 500m }
    }
};
var aboveOrder = new Order
{
    Reference = "ORD-501",
    Channel = OrderChannel.Web,
    Lines =
    {
        new OrderLine { Sku = "SKU-501", Quantity = 1, UnitPrice = 501m }
    }
};

var belowResult = coordinator.ResolveTender(belowOrder, customer);
var atResult = coordinator.ResolveTender(atOrder, customer);
var aboveResult = coordinator.ResolveTender(aboveOrder, customer);

Check.Equal("card", belowResult);
Check.Equal("card", atResult);
Check.Equal("card-3ds", aboveResult);
}
{ // A1: Marketplace order resolves to marketplace escrow
var coordinator = new CheckoutCoordinator();
var order = new Order
{
    Reference = "ORD-MARKET",
    Channel = OrderChannel.Marketplace,
    Lines =
    {
        new OrderLine { Sku = "SKU-M", Quantity = 1, UnitPrice = 40m }
    }
};
var customer = new Customer { Tier = CustomerTier.Standard };

var result = coordinator.ResolveTender(order, customer);

Check.Equal("marketplace-escrow", result);
}
{ // D1: Welcome promotion returns zero after the order reference is redeemed
var coordinator = new CheckoutCoordinator();
var order = new Order
{
    Reference = "ORD-PROMO",
    Channel = OrderChannel.Web,
    Lines =
    {
        new OrderLine { Sku = "SKU-P", Quantity = 1, UnitPrice = 200m }
    }
};

var firstResult = coordinator.ApplyPromo(order, "WELCOME");
var secondResult = coordinator.ApplyPromo(order, "WELCOME");

Check.Equal(20m, firstResult);
Check.Equal(0m, secondResult);
}

